extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	check("no_nc_file", not FileAccess.file_exists("res://assets/audio/sample_nc.wav"), "Il file res://assets/audio/sample_nc.wav deve essere stato rimosso")

	if not FileAccess.file_exists("res://CREDITS.txt"):
		check("credits_exists", false, "Il file res://CREDITS.txt deve esistere")
		return

	var f := FileAccess.open("res://CREDITS.txt", FileAccess.READ)
	if f == null:
		check("open", false, "Impossibile aprire res://CREDITS.txt")
		return
	var text := f.get_as_text()
	f.close()

	check("no_nc_text", not text.contains("sample_nc.wav"), "Il file sample_nc.wav non deve comparire in CREDITS.txt")
	check("bg_obligation", text.contains("Obbligo: Nessuno"), "Per background.png la riga obbligo deve essere 'Obbligo: Nessuno'")
	check("click_obligation", text.contains("Obbligo: Citare autore e fonte"), "Per click.wav la riga obbligo deve essere 'Obbligo: Citare autore e fonte'")
